package ama.meeting;
import ama.access.MeetingAccess;import ama.contract.IdentityContracts.*;import ama.db.TransactionRunner;import ama.task.SubjectFencePort;
import java.sql.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Actual reader/gate/TransactionRunner; JDBC rows and subject fence are substitutes, not MySQL qualification. */
class Task12CommandDiscoveryTest {
 static final String M="00000000-0000-4000-8000-000000000001",R="00000000-0000-4000-8000-000000000002";
 final Actor actor=new Actor("owner",Status.ACTIVE,Set.of(Role.USER));DataSource source;JdbcMeetingAccess access;TransactionRunner tx;JdbcMeetingCommandDiscovery reader;List<String> sql;Map<String,Object> root;String operation,resource;boolean present=true,missingResult=false,disabled=false;int reads;boolean changeReceipt,wrongResult;
 static Map<String,Object> row(Object...values){var m=new LinkedHashMap<String,Object>();for(int n=0;n<values.length;n+=2)m.put((String)values[n],values[n+1]);return m;}
 @BeforeEach void setup()throws Exception {
  source=mock(DataSource.class);sql=new ArrayList<>();root=row("id",M,"owner_id","owner","revision",9L,"access_revision",3L,"cancel_epoch",0L,"stage","ENTRY","lifecycle","ACTIVE","governance_state","ACTIVE","ever_published",false,"info_revision_id",R,"roster_revision_id",null);
  when(source.getConnection()).thenAnswer(call->{var c=mock(Connection.class);when(c.getAutoCommit()).thenReturn(true);when(c.createStatement()).thenReturn(mock(Statement.class));when(c.prepareStatement(anyString())).thenAnswer(q->{String text=q.getArgument(0);sql.add(text);assertTrue(text.startsWith("SELECT "),text);var st=mock(PreparedStatement.class);when(st.getConnection()).thenReturn(c);when(st.executeQuery()).thenAnswer(ignore->result(rows(text)));return st;});return c;});
  tx=new TransactionRunner(source);var fences=mock(SubjectFencePort.class);var subject=mock(SubjectFencePort.LockedSubject.class);when(subject.businessVersion()).thenReturn(9L);when(fences.lock(any(),eq(false))).thenReturn(Optional.of(subject));access=new JdbcMeetingAccess(source,tx,fences);reader=new JdbcMeetingCommandDiscovery(source,tx,access,WorkspaceReadBudget.DEFAULT);
 }
 List<Map<String,Object>> rows(String query){
  if(query.contains(" FROM enterprise_identity "))return List.of(query.startsWith("SELECT status")?row("status",disabled?"DISABLED":"ACTIVE"):row("enterprise_id","owner","status",disabled?"DISABLED":"ACTIVE"));
  if(query.contains(" FROM meeting "))return List.of(root);
  if(query.contains(" FROM idempotency_record ")){reads++;return !present?List.of():List.of(row("actor_id","owner","resource_id",resource,"operation",operation,"key_hash",MeetingDigests.fields("original key"),"request_hash",operation.equals("CREATE")?MeetingDigests.fields("meeting-create-v1"):"a".repeat(64),"state","SUCCEEDED","result_id",changeReceipt&&reads>1?M:R,"http_status",Set.of("CREATE","UPLOAD_BEGIN").contains(operation)?201:200));}
  if(query.contains(" FROM upload_session "))return missingResult?List.of():List.of(row("meeting_id",M));
  if(query.contains(" FROM meeting_info_revision ")||query.contains(" FROM roster_revision "))return missingResult?List.of():List.of(row("meeting_id",M,"revision",operation.equals("CREATE")?(wrongResult?1L:0L):2L,"state",wrongResult?"DRAFT":"CONFIRMED"));
  throw new AssertionError(query);
 }
 ResultSet result(List<Map<String,Object>> rows)throws Exception {var rs=mock(ResultSet.class);var i=new AtomicInteger(-1);var columns=rows.isEmpty()?List.<String>of():new ArrayList<>(rows.getFirst().keySet());var metadata=mock(ResultSetMetaData.class);when(metadata.getColumnCount()).thenReturn(columns.size());when(rs.getMetaData()).thenReturn(metadata);when(rs.next()).thenAnswer(x->i.incrementAndGet()<rows.size());when(rs.getString(anyInt())).thenAnswer(x->(String)rows.get(i.get()).get(columns.get((int)x.getArgument(0)-1)));when(rs.getString(anyString())).thenAnswer(x->(String)rows.get(i.get()).get(x.getArgument(0)));when(rs.getLong(anyInt())).thenAnswer(x->((Number)rows.get(i.get()).get(columns.get((int)x.getArgument(0)-1))).longValue());when(rs.getInt(anyInt())).thenAnswer(x->((Number)rows.get(i.get()).get(columns.get((int)x.getArgument(0)-1))).intValue());when(rs.getLong(anyString())).thenAnswer(x->((Number)rows.get(i.get()).get(x.getArgument(0))).longValue());when(rs.getBoolean(anyString())).thenAnswer(x->Boolean.TRUE.equals(rows.get(i.get()).get(x.getArgument(0))));return rs;}
 ama.contract.WorkspaceContracts.CommandLookup lookup(String op){operation=op;resource=op.equals("CREATE")?"meetings":M;return reader.lookup(actor,operation,resource,"original key");}
 @Test void createUsesOriginalAssociationAndSeparateCurrentObservation(){var found=lookup("CREATE");assertEquals("FOUND",found.status());assertEquals(R,found.association().resultId());assertEquals("0",found.association().acceptedRevisionToken());assertEquals("9",found.current().revisionToken());assertEquals(2,reads);assertTrue(sql.stream().noneMatch(q->q.contains("SELECT *")||q.contains("display_name")||q.contains("summary")||q.contains("request_manifest")));}
 @Test void allScopedFamiliesAreReadOnlyAndExposeOnlyTheirActualParent(){for(String op:List.of("SAVE_INFO","CONFIRM_ROSTER","UPLOAD_BEGIN")){var found=lookup(op);assertEquals(M,found.association().meetingId());assertEquals(op.equals("UPLOAD_BEGIN")?null:"2",found.association().acceptedRevisionToken());}assertTrue(sql.stream().noneMatch(q->q.contains("provider_upload_token")||q.contains("object_key")));}
 @Test void absenceIsExplicitAndStillRequiresCurrentScopedOwner(){present=false;assertNull(lookup("CREATE").current());assertEquals("9",lookup("SAVE_INFO").current().revisionToken());root.put("owner_id","other");int before=reads;assertThrows(MeetingAccess.AccessDeniedException.class,()->lookup("SAVE_INFO"));assertEquals(before,reads);}
 @Test void disabledIdentityNeverReadsReceipt(){disabled=true;assertThrows(MeetingAccess.AccessDeniedException.class,()->lookup("CREATE"));assertEquals(0,reads);}
 @Test void changedCreationAssociationCannotBeExposed(){changeReceipt=true;assertThrows(WorkspaceReadBudget.Unavailable.class,()->lookup("CREATE"));}
 @Test void danglingResultFailsWholeLookup(){missingResult=true;for(String op:List.of("CREATE","SAVE_INFO","CONFIRM_ROSTER","UPLOAD_BEGIN"))assertThrows(WorkspaceReadBudget.Unavailable.class,()->lookup(op));}
 @Test void requestBoundsAndCancellationPrecedeSql(){assertThrows(IllegalArgumentException.class,()->reader.lookup(actor,"CREATE","meetings","x".repeat(4097)));assertTrue(sql.isEmpty());Thread.currentThread().interrupt();try{assertThrows(WorkspaceReadBudget.Unavailable.class,()->lookup("CREATE"));assertTrue(sql.isEmpty());}finally{Thread.interrupted();}}
 @Test void impossibleCreateRevisionAndUnconfirmedRosterCannotBeAcceptedAssociations(){wrongResult=true;assertAll(()->assertThrows(WorkspaceReadBudget.Unavailable.class,()->lookup("CREATE")),()->assertThrows(WorkspaceReadBudget.Unavailable.class,()->lookup("CONFIRM_ROSTER")));}
 @Test void cumulativeDigestReservationRejectsBeforeEitherHashAllocation(){
  var limits=new WorkspaceReadBudget.Limits(40000,100000,100000,100000,4096,16384,java.time.Duration.ofSeconds(5));var bounded=new JdbcMeetingCommandDiscovery(source,tx,access,limits);
  try(var hashes=mockStatic(MeetingDigests.class)){assertThrows(WorkspaceReadBudget.Unavailable.class,()->bounded.lookup(actor,"SAVE_INFO",M,"k".repeat(4096)));hashes.verifyNoInteractions();}assertTrue(sql.isEmpty());
 }
}
